  try (PreparedStatement ps = conn.prepareStatement("UPDATE orders SET status=? WHERE id=?")) {
    ps.setString(1, newStatus); ps.setInt(2, id); ps.executeUpdate();
  }
}

static int updateWithVersion(Connection conn, int id, BigDecimal newBalance, int expectedVersion) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("UPDATE accounts SET balance=?, version=version+1 WHERE id=? AND version=?")) {
    ps.setBigDecimal(1, newBalance); ps.setInt(2, id); ps.setInt(3, expectedVersion);
    return ps.executeUpdate();
  }
}

