static boolean updateWithRetry(Connection conn, int id, BigDecimal delta, int maxAttempts) throws SQLException {
  for (int attempt = 0; attempt < maxAttempts; attempt++) {
    int[] state = readBalanceAndVersion(conn, id);
    BigDecimal newBalance = new BigDecimal(state[0]).add(delta);
    if (updateWithVersion(conn, id, newBalance, state[1]) > 0) return true;
  }
  return false;
}

