static void updateWithAudit(Connection conn, int id, String newEmail) throws SQLException {
  String oldEmail = readEmail(conn, id);
  try (PreparedStatement audit = conn.prepareStatement("INSERT INTO audit_log (message) VALUES (?)")) {
    audit.setString(1, "Zmiana email dla id=" + id + ": " + oldEmail + " -> " + newEmail);
    audit.executeUpdate();
  }
  updateEmail(conn, id, newEmail);
}

