static int executeUpdateAndValidate(PreparedStatement ps, int expectedMinRows) throws SQLException {
  int rows = ps.executeUpdate();
  if (rows < expectedMinRows) throw new IllegalStateException("Oczekiwano co najmniej " + expectedMinRows + ", zmieniono: " + rows);
  return rows;
}

static void updatePartial(Connection conn, int id, Map<String, Object> fields) throws SQLException {
  List<String> setClauses = new ArrayList<>();
  List<Object> values = new ArrayList<>();
  for (var entry : fields.entrySet()) { setClauses.add(entry.getKey() + " = ?"); values.add(entry.getValue()); }
  String sql = "UPDATE users SET " + String.join(", ", setClauses) + " WHERE id = ?";
  try (PreparedStatement ps = conn.prepareStatement(sql)) {
    int i = 1;
    for (Object v : values) ps.setObject(i++, v);
    ps.setInt(i, id);
    ps.executeUpdate();
  }
}

